import * as T from 'three';
export function createLaserVisual(){const root=new T.Group();root.name='VRLaserEyes';for(const side of [-1,1]){const material=new T.MeshBasicMaterial({color:'#ff264c',transparent:true,opacity:1,blending:T.AdditiveBlending,depthWrite:false,toneMapped:false}),beam=new T.Mesh(new T.CylinderGeometry(.035,.035,1,8),material);beam.rotation.x=Math.PI/2;beam.position.x=side*.085;root.add(beam);const core=new T.Mesh(new T.CylinderGeometry(.012,.012,1,6),new T.MeshBasicMaterial({color:'#fff0f4',transparent:true,depthWrite:false,toneMapped:false}));core.rotation.x=Math.PI/2;core.position.x=side*.085;root.add(core);}root.visible=false;return root;}
export function poseLaserVisual(root,a,playing){root.visible=playing&&a.hunterCharacter===1&&a.laserTime>0;if(!root.visible)return;const range=a.laserRange||0;root.position.set(a.laserX,1.99,a.laserZ);root.rotation.y=a.laserAngle;for(const beam of root.children){beam.scale.y=range;beam.position.z=range/2;beam.material.opacity=Math.min(1,a.laserTime/.12);}}
